<?php
require 'config.php'; require_customer();
if (!isset($_SESSION['customer_cart'])) $_SESSION['customer_cart'] = [];
$cart =& $_SESSION['customer_cart']; $errors = []; $receipt = $_SESSION['customer_receipt'] ?? null; unset($_SESSION['customer_receipt']);
$duitkuCheckout = $_SESSION['duitku_checkout'] ?? null; unset($_SESSION['duitku_checkout']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    if ($action === 'add') {
        $id = (int)($_POST['id_produk'] ?? 0); $qty = max(1, (int)($_POST['jumlah'] ?? 1));
        $st = $pdo->prepare('SELECT id_produk,nama_produk,harga_jual,stok,gambar FROM produk WHERE id_produk=?'); $st->execute([$id]); $product = $st->fetch();
        if (!$product || (int)$product['stok'] < 1) $errors[] = 'Produk sedang tidak tersedia.';
        else { $found = false; foreach ($cart as &$item) if ($item['id_produk'] === $id) { $item['jumlah'] = min((int)$product['stok'], $item['jumlah'] + $qty); $found = true; break; } unset($item); if (!$found) $cart[] = ['id_produk'=>$id,'nama_produk'=>$product['nama_produk'],'harga_jual'=>$product['harga_jual'],'stok'=>$product['stok'],'jumlah'=>min($qty,(int)$product['stok'])]; }
    } elseif ($action === 'remove') { $i=(int)($_POST['index']??-1); if(isset($cart[$i])) array_splice($cart,$i,1);
    } elseif ($action === 'checkout') {
        $total=0; foreach($cart as $item) $total += $item['harga_jual']*$item['jumlah'];
$paymentMethod=$_POST['metode_pembayaran']??'tunai'; $payment=in_array($paymentMethod,['qris','duitku'],true)?$total:(float)($_POST['pembayaran']??0); if(!$cart)$errors[]='Keranjang masih kosong.'; if($payment<$total)$errors[]='Pembayaran kurang dari total belanja.';
if($paymentMethod==='duitku' && !duitku_enabled()) $errors[]='Pembayaran Duitku belum dikonfigurasi oleh administrator.';
if(!$errors) try { $proof=null; $orderId='TK'.date('ymdHis').random_int(100,999); $customer=$pdo->prepare('SELECT nama,email FROM pelanggan WHERE id_pelanggan=?'); $customer->execute([$_SESSION['customer']['id_pelanggan']]); $customer=$customer->fetch() ?: ['nama'=>'Pelanggan','email'=>'']; $productDetails=implode(', ',array_map(fn($item)=>$item['nama_produk'].' x'.$item['jumlah'],$cart)); $receiptItems=$cart; $pdo->beginTransaction(); $check=$pdo->prepare('SELECT stok FROM produk WHERE id_produk=? FOR UPDATE'); $insert=$pdo->prepare('INSERT INTO transaksi (id_pelanggan,tanggal,nama_barang,jumlah,harga_satuan,total,metode_pembayaran,bukti_pembayaran,duitku_order_id,status_pesanan) VALUES (?,CURDATE(),?,?,?,?,?,?,?,?)'); $reduce=$pdo->prepare('UPDATE produk SET stok=stok-? WHERE id_produk=?'); foreach($cart as $item){$check->execute([$item['id_produk']]);$stock=(int)$check->fetchColumn();if($stock<$item['jumlah'])throw new RuntimeException('Stok '.$item['nama_produk'].' tidak mencukupi.');$insert->execute([$_SESSION['customer']['id_pelanggan'],$item['nama_produk'],$item['jumlah'],$item['harga_jual'],$item['harga_jual']*$item['jumlah'],$paymentMethod,$proof,$paymentMethod==='duitku'?$orderId:null,$paymentMethod==='duitku'?'pending':'selesai']);$reduce->execute([$item['jumlah'],$item['id_produk']]);} $pdo->commit(); $cart=[]; if($paymentMethod==='duitku'){ $paymentPage=duitku_request_payment($orderId,$total,$productDetails,$customer); $pdo->prepare('UPDATE transaksi SET duitku_reference=? WHERE duitku_order_id=?')->execute([$paymentPage['reference'],$orderId]); $_SESSION['duitku_checkout']=['reference'=>$paymentPage['reference'],'order'=>$orderId]; go('belanja.php'); } $_SESSION['customer_receipt']=['items'=>$receiptItems,'total'=>$total,'payment'=>$payment,'change'=>$payment-$total,'date'=>date('d/m/Y H:i')];go('belanja.php'); } catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex->getMessage();}
    }
}
$q=trim($_GET['q']??'');$cat=trim($_GET['kategori']??'');$where=[];$params=[];if($q!==''){$where[]='nama_produk LIKE ?';$params[]="%$q%";}if($cat!==''){$where[]='kategori=?';$params[]=$cat;}$st=$pdo->prepare('SELECT * FROM produk'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY nama_produk');$st->execute($params);$products=$st->fetchAll();$categories=$pdo->query('SELECT DISTINCT kategori FROM produk ORDER BY kategori')->fetchAll(PDO::FETCH_COLUMN);$cartTotal=0;$cartItems=0;foreach($cart as $item){$cartTotal+=$item['harga_jual']*$item['jumlah'];$cartItems+=$item['jumlah'];}
$title='Belanja';include 'includes/customer_header.php'; ?>
<div class="shop-page-shell">
<?php if ($duitkuCheckout): ?><div class="alert" style="background:#eff6ff;color:#1e3a8a;border:1px solid #bfdbfe"><strong>Reference Pembayaran Duitku</strong><div style="display:flex;gap:8px;margin-top:8px"><input id="duitku-reference" value="<?= e($duitkuCheckout['reference']) ?>" readonly style="flex:1;background:#fff;border:1px solid #93c5fd;border-radius:6px;padding:9px;font-weight:700;color:#1e3a8a"><button type="button" class="btn" onclick="navigator.clipboard.writeText(document.getElementById('duitku-reference').value).then(()=>this.textContent='Tersalin')">Salin Reference</button></div><small>Copy kode ini jika ingin digunakan pada halaman Demo Transaction Duitku.</small></div><?php endif; ?>
<?php if($errors): ?><div class="alert err"><?= e(implode(' ', $errors)) ?></div><?php endif; ?>
<?php if($receipt): ?><div class="receipt-print"><div class="receipt-head"><strong>TOKOKU</strong><span>STRUK PEMBELIAN</span></div><p><?= e($receipt['date']) ?><br>Pelanggan: <?= e($_SESSION['customer']['nama']) ?></p><hr><?php foreach($receipt['items'] as $item): ?><div class="receipt-line"><span><?= e($item['nama_produk']) ?> x<?= (int)$item['jumlah'] ?></span><strong><?= rupiah($item['harga_jual']*$item['jumlah']) ?></strong></div><?php endforeach; ?><hr><div class="receipt-line"><span>Total</span><strong><?= rupiah($receipt['total']) ?></strong></div><div class="receipt-line"><span>Kembalian</span><strong><?= rupiah($receipt['change']) ?></strong></div><button class="btn" onclick="window.print()">Cetak Struk</button></div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script><?php endif; ?>
<div class="page-heading shop-heading"><div><span class="eyebrow eyebrow-dark">TOKOKU SHOP</span><h1>Belanja Produk</h1><p class="sub">Halo, <?= e($_SESSION['customer']['nama']) ?>. Temukan produk favoritmu hari ini.</p></div><div class="shop-heading-note"><span class="sparkle">✦</span><span>Belanja lebih nyaman<br><small>Produk pilihan untukmu</small></span></div></div>
<div class="card product-toolbar"><form method="get" class="product-filters"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Cari produk..."><select name="kategori"><option value="">Semua kategori</option><?php foreach($categories as $c): ?><option value="<?= e($c) ?>" <?= $cat===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select><button class="btn">Cari</button></form></div>
<div class="shop-layout"><div class="product-catalog shop-products"><?php foreach($products as $p): ?><article class="catalog-card"><div class="catalog-image"><?php if($p['gambar']): ?><img src="uploads/produk/<?= e($p['gambar']) ?>" alt="<?= e($p['nama_produk']) ?>"><?php else: ?><span>📦</span><?php endif; ?><span class="stock-label <?= $p['stok']?'available':'empty-stock' ?>"><?= $p['stok']?'Stok Tersedia':'Stok Habis' ?></span></div><div class="catalog-body"><span class="catalog-category"><?= e($p['kategori']) ?></span><h2><?= e($p['nama_produk']) ?></h2><div class="catalog-meta"><strong><?= rupiah($p['harga_jual']) ?></strong><span><?= (int)$p['stok'] ?> stok</span></div><form method="post"><input type="hidden" name="action" value="add"><input type="hidden" name="id_produk" value="<?= (int)$p['id_produk'] ?>"><button class="btn detail-btn" <?= !$p['stok']?'disabled':'' ?>><?= $p['stok']?'Tambah ke Keranjang':'Stok Habis' ?></button></form></div></article><?php endforeach; ?></div><aside class="card cart-panel"><div class="cart-title"><div><h2>Keranjang</h2><p><?= $cartItems ?> barang dipilih</p></div><span class="cart-badge"><?= $cartItems ?></span></div><?php if(!$cart): ?><div class="cart-empty">Keranjang masih kosong.</div><?php else: foreach($cart as $i=>$item): ?><div class="cart-line"><div><strong><?= e($item['nama_produk']) ?></strong><small><?= (int)$item['jumlah'] ?> x <?= rupiah($item['harga_jual']) ?></small></div><strong><?= rupiah($item['jumlah']*$item['harga_jual']) ?></strong><form method="post"><input type="hidden" name="action" value="remove"><input type="hidden" name="index" value="<?= $i ?>"><button class="cart-remove">×</button></form></div><?php endforeach; endif; ?><div class="cart-total"><span>Total</span><strong><?= rupiah($cartTotal) ?></strong></div><form method="post" class="checkout-form"><input type="hidden" name="action" value="checkout"><label>Pembayaran<input type="number" name="pembayaran" min="<?= $cartTotal ?>" required placeholder="Uang pembayaran"></label><button class="btn checkout-btn" <?= !$cart?'disabled':'' ?>>Bayar Sekarang</button></form></aside></div>
 </div>
<?php if ($duitkuCheckout): ?><script src="https://app-sandbox.duitku.com/lib/js/duitku.js"></script><script>
