<script>
document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('.checkout-form');if(!form)return;const label=document.createElement('label');label.textContent='Metode Pembayaran';const select=document.createElement('select');select.name='metode_pembayaran';select.innerHTML='<option value="tunai">Tunai</option><option value="duitku">Duitku (QRIS / DANA / ShopeePay)</option>';label.appendChild(select);const paymentInput=form.querySelector('input[name="pembayaran"]');const paymentLabel=paymentInput.closest('label');select.addEventListener('change',()=>{const online=select.value==='duitku';paymentLabel.hidden=online;paymentInput.required=!online});form.insertBefore(label,form.querySelector('label'));});
</script>
